INSERT INTO `default_notification_templates` (`id`, `notification_description`, `id_template`, `active`) VALUES
(3, 'Notify the customer when a new shipment is created or a waybill is issued for their package.', 6, 1),
(4, 'Notify the customer when their package is tracked.', 6, 1),
(5, 'Notify the customer when their package has been delivered.', 7, 1),
(8, 'Notify the customer when a new package is registered in their locker', 8, 1),
(9, 'Notify customer when their locker package is tracked.', 6, 1),
(10, 'Notify the customer when their locker package has been delivered.', 7, 1);
INSERT INTO `whatsapp_templates` (`id`, `title`, `description`, `body`) VALUES
(1, 'Pending payments', 'This template is used to notify the client of pending payments.', 'Dear [CUSTOMER_FULLNAME], We remind you that you have outstanding bills to pay. Please make the corresponding payment as soon as possible. You can find the details and make payment through this link: [COMPANY_SITE_URL]. Thank you for your prompt attention. Sincerely, [COMPANY_NAME]'),
(6, 'Package tracking', 'Package tracking', '¡Hello [CUSTOMER_FULLNAME]!\n\nYour package with tracking number *[TRACKING_NUMBER]* has had a change of status. You can check the updates in your locker at this link: [COMPANY_SITE_URL]\n\n¡Greetings!\n[COMPANY_NAME]'),
(7, 'Package delivery', 'Package delivery to customer', 'Good news! Your package *[TRACKING_NUMBER]*  has been successfully delivered. Always ready to provide you with exceptional service. Thank you for choosing us!'),
(8, 'New registered package', 'New registered package', 'Dear [CUSTOMER_FULLNAME],\nQWe want to inform you that a new package has been registered in your account.\nTracking number: *[TRACKING_NUMBER]*\n\nWe will keep you informed about the status and progress of your package. Do not hesitate to contact us if you have any questions or need more information, via WhatsApp https://EXAMPLE.COM\n¡Thank you for trusting us to send your packages!\n\nGreetings,\nThe team of [COMPANY_NAME]');
